def gen_random_key(size=32):
    """
    Generate a cryptographically-secure random key. This is done by using
    Python 2.4's os.urandom, or PyCrypto.
    """
    try:
        # Use the faster os.urandom() function if available.
        return os.urandom(size)
    except:
        # Fallback to PyCrypto if not available.
        import Crypto
        return Crypto.Random.new().read(size)

