def gen_key(key=None, size=32):
    """
    Generate a key. This function tries to use the key passed in, and if that
    fails, it will generate a new key.
    """
    if key is None:
        key = gen_random_key(size)
    elif isinstance(key, str):
        key = key.decode('hex')
    elif not isinstance(key, basestring):
        raise TypeError('Key must be a string or buffer.')
    elif len(key) < size:
        raise ValueError('Key must be at least %d bytes long.' % size)
    return key[:size]

def gen_iv(iv=None, size=16):
    """
    Generate an IV. This function tries to use the IV passed in, and if that
    fails, it will generate a new IV.
    """
    if iv is None:
        iv = gen_random_key(size)
    elif isinstance(iv, str):
        iv = iv.decode('hex')
    elif not isinstance(iv, basestring):
        raise TypeError('IV must be a string or buffer.')
    elif len(iv) < size:
        raise ValueError('IV must be at least %d bytes long.' % size)
    return iv[:size]

def gen_salt(salt=None, size=8):
    """
    Generate a salt. This function tries to use the salt passed in, and if that
    fails, it will generate a new salt.
    """
    if salt is None:
        salt = gen_random_key(size)
    elif isinstance(salt, str):
        salt = salt.decode('hex')
    elif not isinstance(salt, basestring):
        raise TypeError('Salt must be a string or buffer.')
    elif len(salt) < size:
